const up=new T.Vector3(0,1,0);
export const snowBodyLimit=.22;
export function snowBallLimit(baseRadius=0){return baseRadius?baseRadius*.63:snowBodyLimit;}
export function snowMotion(yaw,forward,side){return new T.Vector3(Math.sin(yaw)*forward-Math.cos(yaw)*side,0,Math.cos(yaw)*forward+Math.sin(yaw)*side);}
export function snowPoint(x,z){let y=Math.sqrt(Math.max(1,100-x*x-z*z));for(let i=0;i<3;i++){const theta=Math.atan2(Math.hypot(x,z),y),r=snowRadius(theta,Math.atan2(z,x))+.018;y=Math.sqrt(Math.max(1,r*r-x*x-z*z));}return new T.Vector3(x,y,z);}

function disposePiece(root){root.removeFromParent();root.traverse(o=>{o.geometry?.dispose();if(o.material){for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose();}});}
