 if(state.tool==='duck'){if(!peer.snowClamp){peer.snowClamp=createDuckClamp(peer.arms[0]);peer.snowClamp.position.set(0,-.27,.04);}peer.snowClamp.visible=true;peer.snowClamp.children.forEach(a=>a.rotation.z=a.userData.side*Math.sin(state.clamping*Math.PI)*.4);}else if(peer.snowClamp)peer.snowClamp.visible=false;
